using RoguePrince.CheatMenu;using MotherBase.EntityFramework;using UnityEngine;
int passed=0,failed=0;void Check(string name,Action a){try{a();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Eq<T>(T a,T b){if(!Equals(a,b))throw new Exception($"Expected {b}, got {a}");}
void Refuse(Action a){try{a();throw new Exception("unsafe request accepted");}catch(InvalidOperationException){}catch(ArgumentException){}}
(GameSession game,SceneActions scenes,BossPhaseActions actions,Entity boss,BossComponentBase component) Setup(string kind="Altan")
{
 UnityEngine.Object.All.Clear();NativePhase.Calls=0;NativePhase.Advance=true;NativePhase.ThrowAfterDamage=false;DebugService.Ready=true;Application.isFocused=true;Time.timeScale=1;Time.realtimeSinceStartup=0;RunTools.RunId=1;SceneActions.flow=new();SceneActions.level=new();var game=new GameSession();var room=new LevelRoomData();SceneActions.map=new(){room=room};game.Player.Add(new RoomStateComponent{currentRoom=room});
 var e=new Entity{context=game.Player.context};e.Add(new MobComponent());e.Add(new Damageable());e.Add(new RoomStateComponent{currentRoom=room});e.Add(new AIStateComponent());
 BossComponentBase c=kind switch{"Altan"=>new AltanBossComponent(),"Baatar"=>new BaatarBossComponent(),"Berude"=>new GoatBossComponent(),"CorruptedNogai"=>new CorruptedNogaiBossComponent(),"Kaali"=>new KaaliBossComponent(),_=>new NogaiBossComponent()};
 TestBrain b=kind switch{"Altan"=>new AltanBossBrain(),"Baatar"=>new BaatarBossBrain(),"Berude"=>new GoatBossBrain(),"CorruptedNogai"=>new CorruptedNogaiBrain(),"Kaali"=>new KaaliBossBrain(),_=>new NogaiBossBrain()};NativePhase.OriginalBoss=e;e.Add(c);e.Add(new BSAIInput{brain=b});var scenes=new SceneActions();var actions=new BossPhaseActions(game,scenes);actions.Refresh();return(game,scenes,actions,e,c);
}
foreach(var kind in new[]{"Altan","Baatar","Berude","CorruptedNogai","Kaali","Nogai"})Check("native routing and index confirmation "+kind,()=>{var(g,s,a,e,c)=Setup(kind);Eq(a.Entries.Count,1);a.Request(a.Entries[0],()=>{});a.Tick();Eq(NativePhase.Kind,kind);Eq(NativePhase.Calls,1);Eq(a.Busy,false);if(!a.Status.Contains("1 → 2"))throw new Exception("No native phase confirmation");});
Check("final and opening phases never dispatch native damage",()=>{foreach(var phase in new[]{0,3}){var(g,s,a,e,c)=Setup();c.currentPhaseIndex=phase;Refuse(()=>a.Request(a.Entries[0],()=>{}));Eq(NativePhase.Calls,0);}});
Check("wrong brain and foreign context never become selected targets",()=>{var(g,s,a,e,c)=Setup();e.GetComponent<BSAIInput>().brain=new NogaiBossBrain();a.Refresh();Eq(a.Entries.Count,0);var(g2,s2,a2,e2,c2)=Setup();e2.context=new();a2.Refresh();Eq(a2.Entries.Count,0);});
Check("non arena refuses native phase entry",()=>{var(g,s,a,e,c)=Setup();s.Arena=false;Refuse(()=>a.Request(a.Entries[0],()=>{}));Eq(NativePhase.Calls,0);});
Check("missing native debug entry and idle AI never dispatch",()=>{var(g,s,a,e,c)=Setup();DebugService.Ready=false;Refuse(()=>a.Request(a.Entries[0],()=>{}));Eq(NativePhase.Calls,0);DebugService.Ready=true;e.GetComponent<AIStateComponent>().stayIdle=true;Refuse(()=>a.Request(a.Entries[0],()=>{}));Eq(NativePhase.Calls,0);});
Check("stale brain and moved room cannot dispatch",()=>{var(g,s,a,e,c)=Setup();e.GetComponent<BSAIInput>().brain=new AltanBossBrain();Refuse(()=>a.Request(a.Entries[0],()=>{}));Eq(NativePhase.Calls,0);var(g2,s2,a2,e2,c2)=Setup();g2.Player.GetComponent<RoomStateComponent>().currentRoom=new();Refuse(()=>a2.Request(a2.Entries[0],()=>{}));Eq(NativePhase.Calls,0);});
Check("focus loss and replacement level cancel without a second damage",()=>{var(g,s,a,e,c)=Setup();NativePhase.Advance=false;a.Request(a.Entries[0],()=>{});Application.isFocused=false;a.Tick();Eq(a.Busy,false);Eq(NativePhase.Calls,1);var(g2,s2,a2,e2,c2)=Setup();NativePhase.Advance=false;a2.Request(a2.Entries[0],()=>{});SceneActions.level=new();a2.Tick();Eq(a2.Busy,false);Eq(NativePhase.Calls,1);});
Check("HP reduction alone never reports phase completion or retries",()=>{var(g,s,a,e,c)=Setup();NativePhase.Advance=false;a.Request(a.Entries[0],()=>{});a.Tick();Eq(a.Busy,true);Time.realtimeSinceStartup=31;a.Tick();Eq(a.Busy,false);Eq(NativePhase.Calls,1);if(!a.Status.Contains("超时"))throw new Exception("Timeout not reported");});
Check("pending duplicate is refused and cancel never reverses damage",()=>{var(g,s,a,e,c)=Setup();NativePhase.Advance=false;a.Request(a.Entries[0],()=>{});Refuse(()=>a.Request(a.Entries[0],()=>{}));Eq(NativePhase.Calls,1);a.Cancel();Eq(a.Busy,false);Eq(e.GetComponent<Damageable>().currentHealth,66f);});
Check("native debug window must bind the selected formal boss",()=>{var(g,s,a,e,c)=Setup();NativePhase.OriginalBoss=new Entity();Refuse(()=>a.Request(a.Entries[0],()=>{}));Eq(NativePhase.Calls,0);});
Check("exception after native damage retains owner until phase confirmation",()=>{var(g,s,a,e,c)=Setup();NativePhase.ThrowAfterDamage=true;try{a.Request(a.Entries[0],()=>{});throw new Exception("Expected native failure");}catch(IOException){}Eq(a.Busy,true);Eq(NativePhase.Calls,1);c.currentPhaseIndex=2;a.Tick();Eq(a.Busy,false);Eq(NativePhase.Calls,1);});
Check("uncertain native damage times out without resubmission",()=>{var(g,s,a,e,c)=Setup();NativePhase.ThrowAfterDamage=true;try{a.Request(a.Entries[0],()=>{});throw new Exception("Expected native failure");}catch(IOException){}Eq(a.Busy,true);Time.realtimeSinceStartup=31;a.Tick();Eq(a.Busy,false);Eq(NativePhase.Calls,1);});
PracticeTests.Run(Check);
Console.WriteLine($"RESULT {passed} passed, {failed} failed");return failed==0?0:1;
